from __future__ import annotations
import copy,random
STATES={'home': ['landing', 'search_results', 'learning_paths', 'signed_in', 'tutorial_menu', 'advertisement'], 'tutorial': ['introduction', 'headings', 'tables', 'chapter_complete', 'mobile_contents', 'advertisement'], 'tryit_editor': ['html', 'css', 'javascript', 'console_error', 'save_code', 'advertisement'], 'exercises': ['catalog', 'question', 'correct', 'incorrect', 'show_answer', 'reset_progress'], 'quiz': ['intro', 'question', 'answered', 'results', 'review_answers', 'exit_quiz'], 'reference': ['index', 'element_detail', 'browser_support', 'filtered', 'copy_example', 'advertisement'], 'courses': ['catalog', 'course_detail', 'curriculum', 'enrolled', 'cart', 'advertisement'], 'certificates': ['overview', 'exam_instructions', 'practice_exam', 'earned', 'verify_certificate', 'exam_confirmation'], 'spaces': ['dashboard', 'file_manager', 'editor', 'preview', 'create_space', 'delete_space'], 'account': ['dashboard', 'profile', 'progress', 'preferences', 'sign_in', 'cookie_preferences']}
POPUPS={'save_code', 'exam_confirmation', 'verify_certificate', 'mobile_contents', 'create_space', 'cookie_preferences', 'tutorial_menu', 'advertisement', 'reset_progress', 'copy_example', 'cart', 'show_answer', 'sign_in', 'delete_space', 'exit_quiz'}
NAV=[('home','home','Home'),('tutorial','menu_book','Tutorial'),('tryit_editor','code','Tryit'),('exercises','edit_note','Exercises'),('quiz','quiz','Quiz'),('reference','description','Reference'),('courses','school','Courses'),('certificates','workspace_premium','Certificates'),('spaces','folder','Spaces'),('account','person','Account')]
LANGUAGES=['HTML','CSS','JavaScript','Python','SQL','Java','C++','React','TypeScript','Bootstrap','Git','PHP']
CHAPTERS=['HOME','Introduction','Editors','Basic','Elements','Attributes','Headings','Paragraphs','Styles','Formatting','Quotations','Comments','Colors','Links','Images','Tables','Lists','Forms','Layout','Responsive','Semantic','Accessibility']
HTML_CODE='<!DOCTYPE html>\n<html>\n<body>\n  <h1>My First Heading</h1>\n  <p>My first paragraph.</p>\n</body>\n</html>'
CSS_CODE='body {\n  background-color: lightblue;\n  font-family: Arial, sans-serif;\n}\nh1 { color: navy; }'
JS_CODE='const message = "Hello, world!";\ndocument.getElementById("demo").textContent = message;'
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'navigation':NAV,'languages':LANGUAGES,'chapters':CHAPTERS,'query':'HTML tables','code':HTML_CODE,'css':CSS_CODE,'js':JS_CODE,'progress':random.randint(25,75),'xp':random.randint(100,1200),'streak':random.randint(1,14),'courses':[{'name':n,'lessons':random.randint(30,70),'progress':random.randint(15,80),'price':95,'description':d} for n,d in [('HTML','Build the structure of web pages'),('CSS','Style layouts and responsive interfaces'),('JavaScript','Make websites interactive'),('Python','Learn programming fundamentals'),('SQL','Work with relational data'),('React','Build reusable UI components')]],'spaces':[{'name':n,'url':n+'.example.test','status':s,'files':f,'updated':'Oct 7, 2026'} for n,s,f in [('portfolio-demo','Published',8),('learning-notes','Draft',5),('recipe-project','Published',12)]],'files':[{'name':n,'icon':i,'size':s} for n,i,s in [('index.html','html','2.1 KB'),('style.css','css','1.4 KB'),('script.js','javascript','960 B'),('images','folder','Folder'),('README.md','description','640 B')]],'references':[{'tag':t,'description':d,'category':c} for t,d,c in [('<a>','Defines a hyperlink','Links'),('<article>','Represents self-contained content','Semantic'),('<button>','Defines a clickable button','Forms'),('<div>','Defines a generic container','Basic'),('<form>','Collects user input','Forms'),('<h1>','Defines a top-level heading','Basic'),('<img>','Embeds an image','Media'),('<input>','Defines an input control','Forms'),('<p>','Defines a paragraph','Basic'),('<section>','Defines a thematic section','Semantic'),('<table>','Defines a table','Tables'),('<video>','Embeds video content','Media')]],'viewer':{'name':'Alex Morgan','email':'alex@example.test'},'sample_index':sample_index}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d['state']=state;d['popup_visible']=state in POPUPS
 if state=='css':d['code']=d['css']
 if state=='javascript':d['code']=d['js']
 if state=='console_error':d['code']='console.log(missingValue);'
 if state=='filtered':d['references']=[r for r in d['references'] if r['category']=='Forms']
 return d
